/* 
    PDF COMPATIBILITY STYLES
    Target: wkhtmltopdf (No Flexbox, No CSS Variables)
*/

.print-format {
    font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
    font-size: 9pt;
    color: #333;
    line-height: 1.3;
}

/* UTILITIES */
.text-center { text-align: center; }
.text-right { text-align: right; }
.text-left { text-align: left; }
.bold { font-weight: bold; }
.mb-10 { margin-bottom: 10px; }

/* 
   THE FLEX REPLACEMENT 
   We use display: table to mimic flexbox rows.
   This ensures columns are equal height and align perfectly.
*/
.layout-grid {
    display: table;
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 15px;
}

.layout-col {
    display: table-cell;
    vertical-align: top;
}

/* Spacer column to mimic gap */
.layout-gap {
    display: table-cell;
    width: 20px; 
}

/* TABLE STYLES (Borders and Padding) */
table {
    width: 100%;
    border-collapse: collapse;
}

/* Standard Data Tables */
.data-table td, .data-table th {
    padding: 4px 6px;
    border: 1px solid #ddd; /* Light gray border */
}

/* Header/Info Tables (Cleaner look) */
.info-table {
    width: 100%;
    border: 1px solid #ddd;
}

.info-table td {
    padding: 3px 5px;
    border-bottom: 1px solid #eee;
}

.info-header {
    background-color: #f5f5f5; /* Light gray background for headers */
    font-weight: bold;
    padding: 5px;
    border-bottom: 1px solid #ddd;
}

/* ITEMS TABLE SPECIFICS */
.items-table {
    margin-top: 10px;
    margin-bottom: 10px;
    border: 1px solid #ccc;
}

.items-header {
    background-color: #eee;
    font-weight: bold;
    text-align: center;
    padding: 6px;
    border: 1px solid #ccc;
    font-size: 8pt;
}

.items-cell {
    padding: 5px;
    border: 1px solid #ccc;
    vertical-align: middle;
}

/* TOTALS SECTION */
.totals-table td, .totals-table th {
    padding: 4px;
}

.grand-total-row {
    background-color: #f0f0f0;
    border-top: 2px solid #333;
    font-size: 10pt;
}

/* LABELS */
.label-cell {
    color: #666;
    font-size: 8.5pt;
    white-space: nowrap;
    width: 1%; /* Shrink to fit content */
}

/* QR Code Container */
.qr-container {
    margin-bottom: 15px;
}

.qr-img {
    width: 130px; 
    height: 130px; 
    border: 1px solid #eee; 
    padding: 5px;
}

/* Bank Details Box */
.bank-details-box {
    border: 1px solid #ddd; 
    padding: 10px; 
    background: #f9f9f9; 
    font-size: 8pt; 
    margin-bottom: 10px;
}

.bank-header {
    border-bottom: 1px solid #ddd; 
    margin-bottom: 5px;
}

/* Signature Area */
.signature-line {
    border-top: 1px solid #333; 
    width: 60%; 
    margin: 0 auto; 
    padding-top: 5px;
}

html:
{#
Sales Invoice Print Format for OPTIMA ZATCA
Version: 3.1 (Split Files)
#}

{# Initialize context #}
{% set ctx = frappe.call('optima_zatca.optima_zatca.print_format.sales_invoice_controller.get_context', doc=doc) %}

{# ==================== MACROS ==================== #}

{% macro bilingual_row(label_en, value, label_ar, value_class='text-center') %}
<tr>
    <td class="label-cell text-left"><strong>{{ label_en }}</strong></td>
    <td class="{{ value_class }}">{{ value or '' }}</td>
    <td class="label-cell text-right" dir="rtl"><strong>{{ label_ar }}</strong></td>
</tr>
{% endmacro %}

{% macro address_section(address, is_seller=false) %}
    {{ bilingual_row('Building No:', address.building_no, 'رقم المبني:') }}
    {{ bilingual_row('Street Name:', address.custom_street_name, 'إسم الشارع:') }}
    {{ bilingual_row('District:', address.custom_district or address.district, 'الحي:') }}
    {{ bilingual_row('City:', address.city, 'المدينة:') }}
    {{ bilingual_row('Country:', address.country, 'الدولة:') }}
    {{ bilingual_row('Postal Code:', address.pincode, 'الرمز البريدي:') }}
{% endmacro %}

{% macro format_currency(amount, currency=none) %}
    {% set curr = currency or doc.currency %}
    <span class="currency-value">{{ frappe.utils.fmt_money(amount or 0, currency=curr) }}</span>
{% endmacro %}

{% macro totals_row(label_en, label_ar, amount, currency=none, is_grand=false) %}
<tr class="{% if is_grand %}grand-total-row{% endif %}">
    <th class="text-left"><strong>{{ label_en }}</strong></th>
    <td class="text-right" style="width: 120px;">
        {{ format_currency(amount, currency) }}
    </td>
    <th class="text-right" dir="rtl"><strong>{{ label_ar }}</strong></th>
</tr>
{% endmacro %}

{# ==================== MAIN CONTENT ==================== #}

<div class="print-format">

    {# ==================== HEADER ==================== #}
    <div class="layout-grid">
        <div class="layout-col" style="width: 55%; vertical-align: middle;">
            {% if letter_head %}
                {{ letter_head }}
            {% else %}
                <h2>{{ ctx.company.company_name }}</h2>
            {% endif %}
        </div>
        
        <div class="layout-gap"></div>

        <div class="layout-col" style="width: 45%;">
            <table class="data-table info-table">
                <thead>
                    <tr>
                        <th class="info-header text-left">{{ ctx.invoice_type.en }}</th>
                        <th class="info-header">&nbsp;</th>
                        <th class="info-header text-right" dir="rtl">{{ ctx.invoice_type.ar }}</th>
                    </tr>
                </thead>
                <tbody>
                    {{ bilingual_row('Invoice No.', doc.name, 'رقم الفاتورة:') }}
                    {{ bilingual_row('Date', frappe.format_date(doc.posting_date, 'dd-MM-YYYY'), 'التاريخ:') }}
                    {{ bilingual_row('Cust Ref:', doc.custom_customer_ref, 'المرجع:') }}
                    {% if doc.po_no %}
                        {{ bilingual_row('PO No:', doc.po_no, 'أمر الشراء:') }}
                    {% endif %}
                </tbody>
            </table>
        </div>
    </div>

    {# ==================== SELLER & CLIENT INFO ==================== #}
    <div class="layout-grid">
        {# SELLER (Left) #}
        <div class="layout-col" style="width: 48%;">
            <table class="info-table">
                <thead>
                    <tr>
                        <td class="info-header" colspan="2">Seller Information</td>
                        <td class="info-header text-right" dir="rtl">بيانات البائع</td>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td class="label-cell">Name:</td>
                        <td class="text-center bold">{{ ctx.company.company_name }}</td>
                        <td class="label-cell text-right" dir="rtl">الإسم:</td>
                    </tr>
                    {{ address_section(ctx.seller_address, is_seller=true) }}
                    {{ bilingual_row('CR No:', ctx.company.custom_commercial_register, 'السجل:') }}
                    {{ bilingual_row('VAT No:', ctx.company.tax_id, 'الضريبي:') }}
                </tbody>
            </table>
        </div>

        {# GAP #}
        <div class="layout-gap"></div>

        {# CLIENT (Right) #}
        <div class="layout-col" style="width: 48%;">
            <table class="info-table">
                <thead>
                    <tr>
                        <td class="info-header" colspan="2">Client Information</td>
                        <td class="info-header text-right" dir="rtl">بيانات العميل</td>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td class="label-cell">Name:</td>
                        <td class="text-center bold">{{ doc.customer }}</td>
                        <td class="label-cell text-right" dir="rtl">الإسم:</td>
                    </tr>
                    {{ address_section(ctx.customer_address) }}
                    {{ bilingual_row('CR No:', ctx.customer_cr_number, 'السجل:') }}
                    {{ bilingual_row('VAT No:', ctx.customer_tax_id, 'الضريبي:') }}
                </tbody>
            </table>
        </div>
    </div>

    {# ==================== ITEMS TABLE ==================== #}
    <table class="items-table data-table">
        <thead>
            <tr>
                <th class="items-header" style="width: 3%;">#</th>
                <th class="items-header" style="width: 12%;">Part No<br>رقم الصنف</th>
                <th class="items-header" style="width: 25%;">Description<br>الوصف</th>
                <th class="items-header" style="width: 5%;">Unit<br>وحدة</th>
                <th class="items-header" style="width: 5%;">Qty<br>الكمية</th>
                <th class="items-header" style="width: 10%;">Price<br>السعر</th>
                <th class="items-header" style="width: 10%;">Total<br>الاجمالي</th>
                <th class="items-header" style="width: 10%;">VAT<br>الضريبة</th>
                <th class="items-header" style="width: 12%;">Net<br>الصافي</th>
            </tr>
        </thead>
        <tbody>
            {% for item in doc.items %}
            <tr>
                <td class="items-cell text-center">{{ item.idx }}</td>
                <td class="items-cell">{{ item.custom_part_number or item.item_code }}</td>
                <td class="items-cell">
                    {{ item.item_name }}
                    {% if item.description != item.item_name %}
                        <div style="font-size: 80%; color: #666;">{{ item.description }}</div>
                    {% endif %}
                </td>
                <td class="items-cell text-center">{{ item.uom }}</td>
                <td class="items-cell text-center">{{ item.qty }}</td>
                <td class="items-cell text-right">{{ "{:.2f}".format(item.rate) }}</td>
                <td class="items-cell text-right">{{ "{:.2f}".format(item.amount) }}</td>
                <td class="items-cell text-right">{{ "{:.2f}".format(item.tax_amount) }}</td>
                <td class="items-cell text-right bold">{{ "{:.2f}".format(item.total_amount) }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    {# ==================== FOOTER SECTION ==================== #}
    <div class="layout-grid" style="page-break-inside: avoid;">
        
        {# LEFT SIDE: QR, Bank, Words #}
        <div class="layout-col" style="width: 50%; padding-right: 15px;">
            
            {# QR Code #}
            <div class="qr-container">
                {% set qr_code = doc.ksa_einv_qr or doc.ksa_einv2_qr %}
                {% if qr_code %}
                <img src="{{ qr_code }}" class="qr-img">
                {% endif %}
            </div>

            {# Bank Details #}
            {% if ctx.bank_details.bank_name %}
            <div class="bank-details-box">
                <div class="bold bank-header">Bank Details / البيانات البنكية</div>
                <table style="width: 100%;">
                    <tr><td width="80">Bank:</td><td>{{ ctx.bank_details.bank_name }}</td></tr>
                    {% if ctx.bank_details.iban %}
                    <tr><td>IBAN:</td><td>{{ ctx.bank_details.iban }}</td></tr>
                    {% endif %}
                    {% if ctx.bank_details.account_number %}
                    <tr><td>Account:</td><td>{{ ctx.bank_details.account_number }}</td></tr>
                    {% endif %}
                </table>
            </div>
            {% endif %}

            {# Amount in Words #}
            <div style="margin-top: 10px; font-style: italic;">
                <strong>Amount in Words:</strong><br>
                {{ frappe.utils.money_in_words(doc.base_grand_total) or doc.in_words }}
            </div>
        </div>

        {# RIGHT SIDE: Totals #}
        <div class="layout-col" style="width: 50%;">
            <table class="totals-table" style="width: 100%;">
                <tbody>
                    {{ totals_row('Total Before Discount', 'المبلغ قبل الخصم', doc.total) }}

                    {% if doc.discount_amount %}
                        {{ totals_row('Total Discount', 'خصم', doc.discount_amount) }}
                    {% endif %}

                    {{ totals_row('Total Before Tax', 'المبلغ قبل الضريبة', doc.net_total) }}

                    {% for tax in doc.taxes %}
                        {% if 'VAT' in (tax.description or '').upper() %}
                            {{ totals_row('VAT (' ~ ctx.vat_rate ~ '%)', 'مجموع الضريبة', tax.tax_amount) }}
                        {% elif 'RETENTION' in (tax.description or '').upper() %}
                            {{ totals_row('Retention', 'الاحتفاظ', tax.tax_amount) }}
                        {% endif %}
                    {% endfor %}

                    {{ totals_row('Grand Total', 'المجموع الاجمالى', doc.grand_total, is_grand=true) }}
                    
                    <tr><td colspan="3" style="height: 10px;"></td></tr>

                    {{ totals_row('Paid Amount', 'المبلغ المدفوع', doc.grand_total - doc.outstanding_amount) }}
                    {{ totals_row('Outstanding', 'الصافي المستحق', doc.outstanding_amount) }}
                </tbody>
            </table>
        </div>
    </div>

    {# ==================== PREPAYMENTS (If Any) ==================== #}
    {% if doc.prepayments_invcoies and doc.prepayments_invcoies|length > 0 %}
    <div style="margin-top: 20px;">
        <div class="info-header">Prepayment Details / تفاصيل الدفعات المقدمة</div>
        <table class="data-table" style="width: 100%; margin-top: 5px;">
            <thead>
                <tr>
                    <th>Ref Invoice</th>
                    <th>Type</th>
                    <th>Taxable</th>
                    <th>Tax</th>
                    <th>Total</th>
                </tr>
            </thead>
            <tbody>
                {% for prepayment in doc.prepayments_invcoies %}
                <tr>
                    <td>{{ prepayment.reference_invoice }}</td>
                    <td>{{ prepayment.prepayment_type }}</td>
                    <td class="text-right">{{ format_currency(prepayment.deducted_taxable_amount or prepayment.taxable_amount) }}</td>
                    <td class="text-right">{{ format_currency(prepayment.deducted_tax_amount or prepayment.tax_amount) }}</td>
                    <td class="text-right">{{ format_currency(prepayment.deducted_grand_total or prepayment.grand_total) }}</td>
                </tr>
                {% endfor %}
            </tbody>
        </table>
    </div>
    {% endif %}

    {# ==================== SIGNATURES ==================== #}
    <div class="layout-grid" style="margin-top: 40px; page-break-inside: avoid;">
        <div class="layout-col text-center">
            <div class="signature-line">
                Prepared by
            </div>
        </div>
        <div class="layout-col text-center">
            <div class="signature-line">
                Received by
            </div>
        </div>
    </div>

</div>

{% if footer %}
<div style="margin-top: 20px;">
    {{ footer }}
</div>
{% endif %}
